88	/// Optional speculative decoder used by the GLM5.2 engine.
89	#[derive(Clone, Debug, Eq, PartialEq, serde::Deserialize, serde::Serialize)]
90	pub enum Glm52Drafter {
91	    None,
92	    /// External DSpark checkpoint.
93	    Dspark(PathBuf),
94	    /// Checkpoint-native layer-78 multi-token prediction decoder.
95	    NativeMtp,
96	}
97	
98	impl Glm52Drafter {
99	    fn enabled(&self) -> bool {
100	        !matches!(self, Self::None)
101	    }
102	
103	    fn is_dspark(&self) -> bool {
104	        matches!(self, Self::Dspark(_))
105	    }
106	
107	    fn is_mtp(&self) -> bool {
108	        matches!(self, Self::NativeMtp)
109	    }
110	
111	    fn dspark_path(&self) -> Option<&Path> {
112	        match self {
113	            Self::Dspark(path) => Some(path),
114	            Self::None | Self::NativeMtp => None,
115	        }
116	    }
117	}
