2022	            TEST_TOPO,
2023	        )
2024	        .expect("cap bytes");
2025	        let reserve = GLM52_VRAM_RESERVE_BYTES;
2026	        let err = derive_max_model_len(
2027	            Some(99_968),
2028	            reserve + one_request - (1 << 20),
2029	            &Glm52Drafter::None,
2030	            0,
2031	            false,
2032	            TEST_TOPO,
2033	        )
2034	        .expect_err("a budget below the one-request pool must fail");
2035	        assert!(err.to_string().contains("--max-model-len"), "{err}");
2036	    }
2037	
2038	    #[test]
2039	    fn requested_cap_below_the_minimum_fails() {
2040	        derive_max_model_len(
2041	            Some(1024),
2042	            free_for(100_032, &Glm52Drafter::None, 0),
2043	            &Glm52Drafter::None,
2044	            0,
2045	            false,
2046	            TEST_TOPO,
2047	        )
2048	        .expect_err("sub-minimum cap must fail");
2049	    }
2050	
2051	    #[test]
2052	    fn prefill_pool_budgets_the_full_slot_count_plus_scratch() {
2053	        let prefill = Glm52PrefillOnlyOptions {
2054	            chunk_size: GLM52_DEFAULT_PREFILL_CHUNK_SIZE,
2055	        };
2056	        let scratch =
2057	            glm52_prefill_scratch_reservation(Some(prefill)).expect("prefill reservation");
2058	        let free = free_for(100_032, &Glm52Drafter::None, 0);
2059	        let decode = derive_max_model_len(None, free, &Glm52Drafter::None, 0, false, TEST_TOPO)
2060	            .expect("decode budget");
2061	        let prefill =
2062	            derive_max_model_len(None, free, &Glm52Drafter::None, scratch, true, TEST_TOPO)
2063	                .expect("prefill budget");
2064	        // Prefill-only budgets the full slot count too (the prefix cache
2065	        // retains released prefixes in the pool headroom), so its cap can
2066	        // only trail the decode cap — by exactly the scratch reservation.
2067	        assert!(
2068	            prefill.max_model_len <= decode.max_model_len,
2069	            "prefill cap {} must not exceed the decode cap {} once both \
2070	             budget the full slot count",
2071	            prefill.max_model_len,
2072	            decode.max_model_len,
2073	        );
2074	        assert_eq!(prefill.reserve_bytes, GLM52_VRAM_RESERVE_BYTES + scratch);
2075	    }
2076	
2077	    #[test]
2078	    fn decode_pool_rounds_each_slots_dangling_token_page() {
2079	        let cap = 4096usize;
2080	        let pages_per_slot = (cap + 1).div_ceil(GLM52_MODEL_LEN_ALIGN);
2081	        assert_eq!(
2082	            glm52_pool_blocks(cap, model::GLM52_MAX_BATCH_PER_RANK),
2083	            model::GLM52_MAX_BATCH_PER_RANK * pages_per_slot + 1
2084	        );
2085	    }
2086	
2087	    #[test]
2088	    fn default_prefill_chunk_reservation_is_stable() {
2089	        let bytes = glm52_prefill_scratch_reservation(Some(Glm52PrefillOnlyOptions {
2090	            chunk_size: GLM52_DEFAULT_PREFILL_CHUNK_SIZE,
2091	        }))
2092	        .expect("prefill reservation");
2093	        // 3 GiB fixed (row-block MoE scratch + sub-tile buffers) plus
2094	        // 160 KiB x 16384 chunk rows of chunk-scale activations.
2095	        assert_eq!(bytes, 5_905_580_032);
2096	    }
2097	}
