117	        // cache, so a GPU radix hit reuses it for free: a hit means the pages
118	        // were never recycled, and their L78 rows are exactly the ones written
119	        // when the main KV was. See `native_mtp_cache_salt` for the
120	        // shifted-token page-boundary caveat this accepts.
121	        crate::Glm52Drafter::NativeMtp | crate::Glm52Drafter::None => !no_prefix_cache,
122	    }
