28	pub(crate) const FP8_BLOCK: usize = 128;
29	const FP8_GEMM_WORKSPACE_BYTES: usize = 32 << 20;
30	
31	/// The batched GEMV's row ceiling: past this the register tile spills and
32	/// the fp8 GEMM path (activation quant + FlashInfer SM100 groupwise GEMM)
33	/// wins — measured on the #812 verify-span buckets, where GEMV-at-48 tripled
34	/// the step time.
