46	    pub(crate) fn new(ctx: &DeviceContext, rows: usize, width: usize) -> Result<Self> {
47	        ensure!(
48	            rows > 0 && rows.is_multiple_of(4) && width.is_multiple_of(FP8_BLOCK),
49	            "GLM5.2 FP8 GEMM scratch requires rows%4=0 and width%128=0"
50	        );
51	        // Scratch construction runs before the bucket's CUDA-graph capture —
52	        // the only legal window for the DSL AOT module load.
53	        pegainfer_kernels::ops::glm52_fp8_dsl_preload();
54	        Ok(Self {
55	            rows,
56	            width,
57	            activation: ctx.stream.alloc_zeros::<u8>(rows * width)?,
58	            activation_scale: ctx
59	                .stream
60	                .alloc_zeros::<f32>(rows * width.div_ceil(FP8_BLOCK))?,
61	            workspace: ctx.stream.alloc_zeros::<u8>(FP8_GEMM_WORKSPACE_BYTES)?,
62	        })
63	    }
