48	/// The bucket is the smallest [`GLM52_DECODE_BUCKETS`] member covering the
49	/// rank's OWN row demand (Σ wants, capped at the max bucket; never smaller
50	/// than its active count — a smaller bucket would silently drop rows).
51	/// Buckets are rank-local: the MoE collectives take each rank's real row
52	/// count and the conservative protocol-max GEMM bound
53	/// (`ep_ranks × GLM52_MAX_BATCH_PER_RANK`), so no rank pays compute for
54	/// another rank's demand (the free-running gates measured the conservative
55	/// bound at zero cost — `docs/models/glm52/free-running-dp.md` §8).
56	/// Every active slot first gets one row (liveness), then the leftover bucket
57	/// capacity extends mid-prefill slots into *spans* (consecutive prompt
58	/// positions batched through one step), round-robin across the hungry slots
59	/// so co-resident prefills drain in parallel; rows past `active_rows` are
60	/// padding (their slot ids are insignificant — see the body). Span rows are
61	/// emitted as one contiguous run per slot — the [`Glm52StepShape`] contract.
62	pub(super) fn plan_step_shape(wants: &[usize; GLM52_MAX_BATCH_PER_RANK]) -> Glm52StepShape {
63	    let demand = wants.iter().sum::<usize>().min(GLM52_MAX_STEP_ROWS);
64	    let bucket = *GLM52_DECODE_BUCKETS
65	        .iter()
66	        .find(|&&rows| rows >= demand.max(1))
67	        .expect("the largest bucket covers every demand by construction");
68	    let spans = plan_prefill_spans(wants, bucket);
69	    let mut slots: [u8; GLM52_MAX_STEP_ROWS] = [0; GLM52_MAX_STEP_ROWS];
70	    let mut dst = 0usize;
71	    for (slot, &span) in spans.iter().enumerate() {
72	        for _ in 0..span {
73	            slots[dst] = slot as u8;
74	            dst += 1;
75	        }
76	    }
77	    // Rows `active_rows..bucket` are padding. Their slot ids are
78	    // insignificant — a bucket may hold more rows than there are slots
79	    // (verify spans, #812), so padding no longer maps onto distinct free
80	    // slots. Every consumer bounds its semantic walk by `active_rows`;

