//! GLM5.2 EP MoE layer weights (router + shared + local expert bank).
//!
//! The Hopper DeepGEMM masked routed chain is gone; production decode runs
//! the SM100 DeepGEMM path in `moe_ep`. This module only holds the layer
//! weight bundle still shared by the model builder.

use crate::moe_decode::Glm52MoeExpertBank;
use crate::moe_decode::Glm52MoeRouterWeights;
use crate::moe_decode::Glm52MoeSharedExpert;

/// One rank's weights for one EP MoE layer: router and shared expert run
/// where the token lives (every rank); the bank holds this rank's local
/// experts.
pub(crate) struct Glm52MoeEp8LayerWeights {
    pub(crate) router: Glm52MoeRouterWeights,
    pub(crate) shared: Glm52MoeSharedExpert,
    pub(crate) bank: Glm52MoeExpertBank,
}

//! Row-batched device buffer whose column width is a type fact.
//!
//! The step scratch used to carry `[T, C]` buffers as untyped `DeviceVec`s,
//! and every consumer re-validated `len == tokens * C` at its own entrance —
//! ~30 `ensure!`s all re-checking what the allocation already established.
//! `Rows<C>` moves the invariant to the construction point: the width is a
//! `const` type parameter, the row count travels with the buffer, and
//! `len == tokens * C` holds by construction. Receivers read the row count
//! from the value and the width from the type instead of re-validating
//! either, and passing a `[T, HIDDEN]` buffer where `[T, VOCAB]` is expected
//! stops compiling.
//!
//! TP note: the widths are compile-time because TP1 is the only supported
//! layout (the whole crate pins its shapes to `config.rs` constants). If a
//! sharded layout ever lands, the const parameter becomes a dimension tag
//! whose per-rank width lives in a rank config — the construction-time
//! invariant and the typed signatures survive that move unchanged.

use anyhow::Result;
use anyhow::ensure;
use cudarc::driver::CudaSlice;
use half::bf16;
use pegainfer_kernels::tensor::DeviceContext;

/// `[tokens, C]` row-major bf16 device buffer; `data.len() == tokens * C` by
/// construction.
pub(crate) struct Rows<const C: usize> {
    data: CudaSlice<bf16>,
    tokens: usize,
}

//! One rank's native-MTP draft round.

use anyhow::Context as _;

use super::RankSlots;
use crate::model::GLM52_DECODE_BUCKETS;
use crate::runner::Glm52MtpAppend;
use crate::runner::Glm52MtpRound;
use crate::runner::Glm52Worker;

/// Native MTP is an EP collective, unlike DSpark, and its collective chain
/// is FIXED: every rank runs the full round (one context forward + the
/// proposal iterations) every step, sized by its OWN appends/proposals —
/// a rank with no work enters with padding rows. No round-kind negotiation,
/// no cross-rank bucket agreement: the per-step collective count is a
/// constant of the code, never a function of fleet state (the free-running
/// fixed-chain discipline, `docs/models/glm52/free-running-dp.md` §4).
pub(super) fn run_mtp_round(
    rank: usize,
    worker: &Glm52Worker,
    slots: &mut RankSlots,
    source_bucket: usize,
    pending_resets: &mut Vec<usize>,
    appends: Vec<Glm52MtpAppend>,
    proposals: Vec<(usize, u32, usize)>,
) -> anyhow::Result<()> {
    let pick_bucket = |rows: usize| {
        GLM52_DECODE_BUCKETS
            .into_iter()
            .find(|&bucket| bucket >= rows.max(1))
            .with_context(|| format!("GLM5.2 native MTP row count {rows} exceeds bucket capacity"))
    };
    #[cfg(test)]
    let probe = crate::freerun_probe::enabled().then(|| {
        (
            appends.is_empty() && proposals.is_empty(),
            std::time::Instant::now(),
        )
    });

